def cloud(cx, cy, w, hi=CL_HI, mid=CL_MID, sh=CL_SH):
    blobs = [(cx, cy, w * .50, w * .16), (cx - w * .28, cy + 2, w * .30, w * .12),
             (cx + w * .30, cy + 2, w * .28, w * .11), (cx - w * .08, cy - 3, w * .30, w * .13)]
    cells = set()
    for bx, by, rx, ry in blobs:
        for y in range(int(by - ry) - 1, int(by + ry) + 2):
            for x in range(int(bx - rx) - 1, int(bx + rx) + 2):
                if ((x - bx) / rx) ** 2 + ((y - by) / ry) ** 2 <= 1.0: cells.add((x, y))
    if not cells: return
    ymax = {}
    for (x, y) in cells: ymax[x] = max(ymax.get(x, -99), y)
    for (x, y) in cells:
        if (x, y - 2) not in cells: P(x, y, hi)          # lit top
        elif y >= ymax[x] - 1: P(x, y, sh)               # shaded belly
        else: P(x, y, mid)
    for x in ymax: P(x, ymax[x], sh)                     # flat shaded base

